package com.kitefoldlabs.bridle.core.model

import kotlinx.serialization.Serializable

/** Stable identifier for persisted entities. Generated by the data layer. */
public typealias EntityId = Long

@Serializable
public enum class KeyAlgorithm(
    public val sshName: String,
) {
    ECDSA_P256("ecdsa-sha2-nistp256"),
    ECDSA_P384("ecdsa-sha2-nistp384"),
    ECDSA_P521("ecdsa-sha2-nistp521"),
    ED25519("ssh-ed25519"),
    RSA("ssh-rsa"),
    ;

    public companion object {
        public fun fromSshName(name: String): KeyAlgorithm? = entries.firstOrNull { it.sshName == name }
    }
}

@Serializable
public enum class KeySource {
    /** Generated inside the Android Keystore; the private key can never leave secure hardware. */
    KEYSTORE,

    /** Imported OpenSSH/PEM key, stored only as AEAD ciphertext under a Keystore-wrapped key. */
    IMPORTED,
}

@Serializable
public data class Identity(
    val id: EntityId = 0,
    val alias: String,
    val source: KeySource,
    val algorithm: KeyAlgorithm,
    /** One-line OpenSSH public key, e.g. `ssh-ed25519 AAAA… comment`. */
    val publicKeyOpenSsh: String,
    val keystoreAlias: String? = null,
    val requireUserAuth: Boolean = false,
    /** Seconds a biometric unlock stays valid; 0 means every signature prompts. */
    val authValiditySeconds: Int = 300,
    val createdAtEpochMs: Long = 0,
) {
    init {
        require(source != KeySource.KEYSTORE || keystoreAlias != null) { "Keystore identities need a keystoreAlias" }
        require(authValiditySeconds >= 0) { "authValiditySeconds must be >= 0" }
    }
}

@Serializable
public data class Group(
    val id: EntityId = 0,
    val name: String,
    val color: Int? = null,
    val defaultIdentityId: EntityId? = null,
    val defaultUsername: String? = null,
)

@Serializable
public data class Host(
    val id: EntityId = 0,
    val label: String,
    val hostname: String,
    val port: Int = DEFAULT_SSH_PORT,
    val username: String,
    val identityId: EntityId? = null,
    val jumpHostId: EntityId? = null,
    val groupId: EntityId? = null,
    val tags: Set<String> = emptySet(),
    val color: Int? = null,
    val favorite: Boolean = false,
    val keepAliveSeconds: Int = DEFAULT_KEEPALIVE_SECONDS,
    /** When set, interactive shells attach to (or create) this tmux session. */
    val defaultTmuxSession: String? = null,
    val startupCommand: String? = null,
    val env: Map<String, String> = emptyMap(),
    val lastConnectedAtEpochMs: Long? = null,
) {
    /** Checks every user-editable field; returns the first problem found. */
    public fun validate(): Validation =
        Validators.all(
            listOf(
                Validators.label(label),
                Validators.hostname(hostname),
                Validators.port(port),
                Validators.username(username),
                defaultTmuxSession?.let(Validators::sessionName) ?: Validation.Valid,
            ) + env.keys.map(Validators::envName) +
                if (keepAliveSeconds in 0..MAX_KEEPALIVE_SECONDS) {
                    Validation.Valid
                } else {
                    Validation.Invalid("keepAliveSeconds", Validation.Reason.OUT_OF_RANGE)
                },
        )

    /** `user@host` or `user@host:port` for display. */
    public val displayTarget: String
        get() {
            val h = if (hostname.contains(':') && !hostname.startsWith("[")) "[$hostname]" else hostname
            return if (port == DEFAULT_SSH_PORT) "$username@$h" else "$username@$h:$port"
        }

    public companion object {
        public const val DEFAULT_SSH_PORT: Int = 22
        public const val DEFAULT_KEEPALIVE_SECONDS: Int = 30
        public const val MAX_KEEPALIVE_SECONDS: Int = 3_600
    }
}

@Serializable
public data class KnownHost(
    val host: String,
    val port: Int,
    val keyType: String,
    /** Base64 of the SSH wire-format public key blob. */
    val publicKeyBase64: String,
    /** `SHA256:` + unpadded base64, as printed by `ssh-keygen -lf`. */
    val fingerprintSha256: String,
    val addedAtEpochMs: Long = 0,
    val lastSeenAtEpochMs: Long = 0,
)

@Serializable
public enum class RestartMode {
    /** `respawn-pane -k`, then run [LaunchProfile.restartCommand] (default: continue the last Claude conversation). */
    RESPAWN_CONTINUE,

    /** `respawn-pane -k`, then run [LaunchProfile.command] (fresh conversation). */
    RESPAWN_FRESH,

    /** Send Ctrl-C twice, then type the command into the existing shell. */
    SEND_KEYS,
}

@Serializable
public enum class LaunchMode {
    /** The pane runs the user's login shell and Bridle types the command (keeps PATH/nvm; pane survives exit). */
    SHELL_HOSTED,

    /** The pane runs the command directly with `remain-on-exit`. */
    DIRECT,
}

@Serializable
public data class LaunchProfile(
    val id: EntityId = 0,
    val hostId: EntityId,
    val name: String,
    val sessionName: String,
    val workingDir: String,
    val command: String = "claude",
    val restartMode: RestartMode = RestartMode.RESPAWN_CONTINUE,
    val restartCommand: String? = "claude --continue",
    val env: Map<String, String> = emptyMap(),
    val mode: LaunchMode = LaunchMode.SHELL_HOSTED,
    val pinned: Boolean = false,
) {
    public fun validate(): Validation =
        Validators.all(
            listOf(
                Validators.label(name),
                Validators.sessionName(sessionName),
                Validators.workingDirectory(workingDir),
                if (command.isBlank()) Validation.Invalid("command", Validation.Reason.BLANK) else Validation.Valid,
            ) + env.keys.map(Validators::envName),
        )

    /** The command used when restarting, honouring [restartMode]. */
    public val effectiveRestartCommand: String
        get() =
            when (restartMode) {
                RestartMode.RESPAWN_CONTINUE -> restartCommand?.takeIf { it.isNotBlank() } ?: command
                RestartMode.RESPAWN_FRESH, RestartMode.SEND_KEYS -> command
            }

    public companion object {
        /** The built-in Claude Code preset. */
        public fun claude(
            hostId: EntityId,
            workingDir: String,
            sessionName: String,
        ): LaunchProfile =
            LaunchProfile(
                hostId = hostId,
                name = "Claude · ${workingDir.trimEnd('/').substringAfterLast('/').ifBlank { "~" }}",
                sessionName = sessionName,
                workingDir = workingDir,
            )
    }
}

@Serializable
public enum class PortForwardType { LOCAL, DYNAMIC }

@Serializable
public data class PortForward(
    val id: EntityId = 0,
    val hostId: EntityId,
    val type: PortForwardType,
    val bindPort: Int,
    val destHost: String? = null,
    val destPort: Int? = null,
    val autoStart: Boolean = false,
) {
    public fun validate(): Validation =
        Validators.all(
            Validators.port(bindPort),
            when (type) {
                PortForwardType.DYNAMIC -> Validation.Valid
                PortForwardType.LOCAL ->
                    Validators.all(
                        Validators.hostname(destHost.orEmpty()),
                        Validators.port(destPort ?: 0),
                    )
            },
        )
}
